"""Operator CLI: serve | check-config | trust-host | bootstrap."""

from __future__ import annotations

import argparse
import asyncio
import logging
import sys
from pathlib import Path

from vps_mcp.backends.validators import VALIDATOR_BINARIES

SUDOERS_TEMPLATE = """\
# /etc/sudoers.d/vps-mcp — generated by `vps-mcp bootstrap --print-sudoers`
#
# Review before installing, then:
#   sudo install -m 0440 vps-mcp.sudoers /etc/sudoers.d/vps-mcp && sudo visudo -c
#
# NOTE: access to the container runtime and to the package manager is root-equivalent by
# nature. This file narrows *which programs* vps-mcp can run; the vps-mcp server itself
# only ever runs fixed command templates (no arbitrary commands, FR-032).

Defaults:{user} env_keep += "DEBIAN_FRONTEND"
Defaults:{user} !requiretty

Cmnd_Alias VPSMCP_SYSTEMD = /usr/bin/systemctl, /bin/systemctl, /usr/bin/journalctl, /bin/journalctl
Cmnd_Alias VPSMCP_PKG = {pkg}
Cmnd_Alias VPSMCP_FILES = /usr/bin/install, /bin/cat, /usr/bin/cat, /bin/rm, /usr/bin/rm
{runtime_alias}{validator_alias}
{user} ALL=(root) NOPASSWD: VPSMCP_SYSTEMD, VPSMCP_PKG, VPSMCP_FILES{extra}
"""

PKG_BINARIES = {
    "apt": "/usr/bin/apt-get",
    "dnf": "/usr/bin/dnf",
}
VALIDATOR_PATHS = {
    "nginx": "/usr/sbin/nginx",
    "sshd": "/usr/sbin/sshd",
    "caddy": "/usr/bin/caddy",
    "haproxy": "/usr/sbin/haproxy",
}


def render_sudoers(user: str, runtime: str, pm: str) -> str:
    runtime_alias = ""
    extra = ""
    if runtime in ("docker", "podman"):
        runtime_alias = f"Cmnd_Alias VPSMCP_RUNTIME = /usr/bin/{runtime}\n"
        extra += ", VPSMCP_RUNTIME"
    validators = ", ".join(VALIDATOR_PATHS[k] for k in VALIDATOR_BINARIES)
    validator_alias = f"Cmnd_Alias VPSMCP_VALIDATE = {validators}\n"
    extra += ", VPSMCP_VALIDATE"
    return SUDOERS_TEMPLATE.format(
        user=user,
        pkg=PKG_BINARIES[pm],
        runtime_alias=runtime_alias,
        validator_alias=validator_alias,
        extra=extra,
    )


def _cmd_serve(args: argparse.Namespace) -> int:
    from vps_mcp.config.loader import ConfigError
    from vps_mcp.server import build_server

    logging.basicConfig(
        stream=sys.stderr,
        level=getattr(logging, args.log_level),
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
    )
    try:
        server = build_server(args.config)
    except ConfigError as exc:
        for e in exc.errors:
            print(f"config error: {e}", file=sys.stderr)
        return 1
    server.run("stdio")
    return 0


def _cmd_check_config(args: argparse.Namespace) -> int:
    from vps_mcp.config.loader import ConfigError, load_config

    try:
        cfg = load_config(args.config)
    except ConfigError as exc:
        for e in exc.errors:
            print(f"ERROR {e}")
        return 1
    print(
        f"OK: vps '{cfg.vps.name}' ({cfg.vps.host}), {len(cfg.service)} declared service(s), "
        f"read_only={cfg.policy.read_only}"
    )
    return 0


def _host_pattern(host: str, port: int) -> str:
    return host if port == 22 else f"[{host}]:{port}"


async def _fetch_host_key(host: str, port: int):  # type: ignore[no-untyped-def]
    import asyncssh

    return await asyncssh.get_server_host_key(host, port)


def _cmd_trust_host(args: argparse.Namespace) -> int:
    kh = Path(args.known_hosts).expanduser()
    try:
        key = asyncio.run(_fetch_host_key(args.host, args.port))
    except Exception as exc:  # noqa: BLE001
        print(f"could not fetch host key from {args.host}:{args.port}: {exc}", file=sys.stderr)
        return 1
    if key is None:
        print("server presented no host key", file=sys.stderr)
        return 1
    pattern = _host_pattern(args.host, args.port)
    line = f"{pattern} {key.export_public_key('openssh').decode().strip()}"
    print(f"Host key for {pattern}: {key.get_algorithm()} {key.get_fingerprint('sha256')}")

    existing = kh.read_text().splitlines() if kh.exists() else []
    same_host = [x for x in existing if x.split() and pattern in x.split()[0].split(",")]
    if line in existing:
        print("already pinned")
        return 0
    if same_host and not args.replace:
        print(
            f"{kh} already pins a DIFFERENT key for {pattern}. If the server was rebuilt on "
            "purpose, rerun with --replace; otherwise this may be an attack.",
            file=sys.stderr,
        )
        return 2
    if not args.yes:
        answer = input("Verify this fingerprint out-of-band. Pin it? [yes/NO] ")
        if answer.strip().lower() != "yes":
            print("not pinned")
            return 1
    kept = [x for x in existing if x not in same_host]
    kh.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    kh.write_text("\n".join([*kept, line]) + "\n")
    kh.chmod(0o600)
    print(f"pinned in {kh}")
    return 0


def _cmd_bootstrap(args: argparse.Namespace) -> int:
    if not args.print_sudoers:
        print("nothing to do; use --print-sudoers", file=sys.stderr)
        return 2
    sys.stdout.write(render_sudoers(args.user, args.runtime, args.pm))
    return 0


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="vps-mcp", description="MCP server for VPS service management")
    sub = p.add_subparsers(dest="command", required=True)

    s = sub.add_parser("serve", help="run the MCP server on stdio")
    s.add_argument("--config", required=True)
    s.add_argument("--log-level", default="INFO", choices=["DEBUG", "INFO", "WARNING", "ERROR"])
    s.set_defaults(func=_cmd_serve)

    c = sub.add_parser("check-config", help="validate the policy file")
    c.add_argument("--config", required=True)
    c.set_defaults(func=_cmd_check_config)

    t = sub.add_parser("trust-host", help="pin the VPS host key in a known_hosts file")
    t.add_argument("--host", required=True)
    t.add_argument("--port", type=int, default=22)
    t.add_argument("--known-hosts", required=True)
    t.add_argument("--replace", action="store_true", help="replace a different pinned key")
    t.add_argument("--yes", action="store_true", help="do not prompt")
    t.set_defaults(func=_cmd_trust_host)

    b = sub.add_parser("bootstrap", help="print setup material for the VPS")
    b.add_argument("--print-sudoers", action="store_true")
    b.add_argument("--user", default="vpsmcp")
    b.add_argument("--runtime", default="docker", choices=["docker", "podman", "none"])
    b.add_argument("--pm", default="apt", choices=["apt", "dnf"])
    b.set_defaults(func=_cmd_bootstrap)
    return p


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    return int(args.func(args))
